/// <summary>
/// Charge through lines creation class
/// MPJ_37288_ChargebackChargethrough_extension (MPJ_3587)
/// </summary>
public class METCBCTInvoiceLinesCreation
{
}

Method.Source:
    /// <summary>
    /// Entry point of the class
    /// </summary>
    /// <param name="args"><c>Args</c></param>
    static void main(Args args)
    {
        METCBCTInvoiceLinesCreation ctInvoiceLinesCreation = METCBCTInvoiceLinesCreation::construct();
        FormDataSource              formDataSource;
        METCBCTInvoiceHeaderTable   invoiceHeaderTable;
        Common                      common;
        common = args.record();        
        if (common.TableId  == tableNum(METCBCTInvoiceHeaderTable))           
        {
            invoiceHeaderTable = args.record();
            if (invoiceHeaderTable.Status == METCBCTInvoiceStatus::Processed)
            {
                throw Error("@MET:ChargethroughInvoiceIsAlreadyProcessed");
            }

            ctInvoiceLinesCreation.createMETCBCTInvoiceLine(args.record());
        }
        else
        {
            throw error(strfmt("@SYS19306","@MET:Posting"));
        }
    
        if (FormDataUtil::isFormDataSource(args.record()))
        {
            formDataSource = FormDataUtil::getFormDataSource(args.record());
            formDataSource.research(true);
        }
    }

/// <summary>
///  Create a new instance of  METCBCTInvoiceCreation class
/// </summary>
/// <returns>
/// A new instance of METCBCTInvoiceCreation class
/// </returns>
public static METCBCTInvoiceLinesCreation construct()
{
    return new METCBCTInvoiceLinesCreation();
}

    /// <summary>
    ///  Create Records in METCBCTInvoiceLine
    /// </summary>
    /// <param name="_cbCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <returns>True if all CT lines are successfully created; otherwise, false.</returns>
    public boolean createMETCBCTInvoiceLine(METCBCTInvoiceHeaderTable _cbCTInvoiceHeaderTable)
    {
        boolean             ret = true;       
        METCBCTInvoiceLine  metCBCTInvoiceLine;

        int fromInfologLine = infologLine();
        fromInfologLine = fromInfologLine == 0 ? fromInfologLine : fromInfologLine + 1;

        ttsbegin;

        if (METCBCTInvoiceLine::exist(_cbCTInvoiceHeaderTable.Number))
        {
            // Show dialog only when this is called from screen, not from interface/data entity
            if (FormDataUtil::isFormDataSource(_cbCTInvoiceHeaderTable))
            {
                boolean confirm = Box::yesNo("@MET:DeleteInvoiceLines",DialogButton::No);
                if(confirm)
                {
                    delete_from metCBCTInvoiceLine
                    where metCBCTInvoiceLine.HeaderNumber == _cbCTInvoiceHeaderTable.Number;
                }
                else
                {
                    Info("@MET:NoRecordsDeleted");
                    ret = false;
                }
            }
            else
            {
                delete_from metCBCTInvoiceLine
                    where metCBCTInvoiceLine.HeaderNumber == _cbCTInvoiceHeaderTable.Number;
            }
        } 

        if (ret)
        {
            boolean enableWETFunctionality = METVendParameters::find().EnableWETFunctionality;
 
            if (enableWETFunctionality && _cbCTInvoiceHeaderTable.WETTaxAmount != 0)
            {
                ret = this.handleWETInvoiceLineCreation(_cbCTInvoiceHeaderTable);
            }
            else
            {
                if (_cbCTInvoiceHeaderTable.InvoiceType == METInvoiceType::ChargeThrough
                    || _cbCTInvoiceHeaderTable.InvoiceType == METInvoiceType::CrossDock
                    || _cbCTInvoiceHeaderTable.InvoiceType == METInvoiceType::RDA
                    || _cbCTInvoiceHeaderTable.InvoiceType == METInvoiceType::SVR)
                {
                    if (abs(_cbCTInvoiceHeaderTable.VendInvoiceGSTAmount) <= (abs(_cbCTInvoiceHeaderTable.VendInvoiceAmtInclGST) - abs(_cbCTInvoiceHeaderTable.VendInvoiceGSTAmount)))
                    {
                        //Percent gstPercent = this.getGSTPercentage(_metCBCTInvoiceHeaderTable);
                        Percent gstPercent = _cbCTInvoiceHeaderTable.getGSTPercentage();
            
                        if (gstPercent > 10)
                        {
                            error("@MET:GSTPercentageIsMoreThan10Pct");
                            ret = false;
                        }
                    }
                    else
                    {
                        error("@MET:GSTPercentageIsMoreThanNetInvoiceAmount");
                        ret = false;
                    }
                }
                
                if (ret)
                {
                    Percent gstPercent = _cbCTInvoiceHeaderTable.getGSTPercentage();
                    ret = this.handleInvoiceLineCreation(_cbCTInvoiceHeaderTable, gstPercent);
                }
            }

            if (!ret)
            {
                // Save infolog in the error description field
                _cbCTInvoiceHeaderTable.selectForUpdate(true);
                _cbCTInvoiceHeaderTable.captureFromInfolog(fromInfologLine);

                delete_from METCBCTInvoiceLine where METCBCTInvoiceLine.HeaderNumber == _cbCTInvoiceHeaderTable.Number;
            }
        }

        ttscommit;

        return ret;
    }

/// <summary>
///  calculate GST percentage
/// </summary>
/// <returns>
/// return real
/// </returns>
/// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
public  amount getRemainingBaseAmount(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable)
{
    Amount  baseAmountForGST    = _metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount*10;
    Amount  remainingBaseAmount = _metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST-baseAmountForGST-_metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount;
    return remainingBaseAmount;
}

    /// <summary>
    /// Create invoice line
    /// </summary>    
    /// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <param name="_metCBCTVendCust"><c>METCBCTVendCust</c></param>
    /// <param name="_amount"><c>amount</c></param>
    /// <param name="_taxGroup"><c>line creation gst group</c></param>
    /// <param name="_allocItemId"><c>Item id from allocation</c></param>
    /// <returns>True if CT line is successfully created; otherwise, false.</returns>
    public boolean createInvoiceLine(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable, 
                                   METCBCTVendCust _metCBCTVendCust, 
                                   Amount _amount, 
                                   //TaxItemGroup _gstGroup='',
                                   TaxGroup _taxGroup = '',
                                   ItemId _allocItemId = '')
    {
        METCBCTInvoiceLine  metCBCTInvoiceLine;        
        boolean             ret = true;
        CustTable           custTable               = CustTable::find(_metCBCTInvoiceHeaderTable.CustomerAccount); 
        VendTable           vendTable               = VendTable::find(_metCBCTInvoiceHeaderTable.VendorAccount);
        METVendTable        metVendTable            = METVendTable::find(vendTable.AccountNum);
        metCBCTInvoiceLine.HeaderNumber             = _metCBCTInvoiceHeaderTable.Number;
        metCBCTInvoiceLine.VendCustType             = _metCBCTVendCust;

        if (_allocItemId)
        {
            metCBCTInvoiceLine.ItemId               = _allocItemId;
        }
        else
        {
            // CB411_412_ChargeThrough
            // This will default the default service item set on the selected vendor account based on if charge through allowed 
            // or cross dock allowed is enabled. If there is no service item defaulted, this field will be blank.
            if (_metCBCTInvoiceHeaderTable.InvoiceType == METInvoiceType::ChargeThrough)
            {
                metCBCTInvoiceLine.ItemId = metVendTable.ChargeThroughServiceItemId;
            }
            else
            {
                metCBCTInvoiceLine.ItemId = metVendTable.CrossDockServiceItemId;
            }
        }              
        metCBCTInvoiceLine.Qty                      = 1;
        metCBCTInvoiceLine.Amount                   = _amount;
        // CB411_412_ChargeThrough Defaults from the ‘Item sales tax group’ selected don the Released product record of the service item selected.
        //metCBCTInvoiceLine.TaxItemGroup             = _gstGroup;
        metCBCTInvoiceLine.TaxItemGroup             = InventTableModule::find(metCBCTInvoiceLine.ItemId, ModuleInventPurchSales::Sales).TaxItemGroupId;

        //metCBCTInvoiceLine.TaxGroup                 = _gstGroup;

        metCBCTInvoiceLine.TaxGroup                 = _taxGroup;

        metCBCTInvoiceLine.InventSiteId     = custTable.InventSiteId;
        metCBCTInvoiceLine.InventLocationId = custTable.InventLocation;
      
        
        // CB411_412_ChargeThrough call modifiedField so it sets financial dimension
        //metCBCTInvoiceLine.FinancialDimension   = METCBCTInvoiceLine::initFinancialDimension(metCBCTInvoiceLine.ItemId,_metCBCTInvoiceHeaderTable.FinancialDimension);
        metCBCTInvoiceLine.modifiedField(fieldNum(METCBCTInvoiceLine, ItemId));
        
        if (metCBCTInvoiceLine.validateWrite())
        {
            metCBCTInvoiceLine.insert();
        }
        else
        {
            error(strFmt("@MET:CBCTInvoiceLineValidateWrite", metCBCTInvoiceLine.VendCustType, metCBCTInvoiceLine.ItemId));
            ret = false;
        }

        return ret;
    }

    /// <summary>
    /// Create invoice line
    /// </summary>
    /// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <param name="_metCBCTVendCust"><c>METCBCTVendCust</c></param>
    /// <param name="_amount"><c>amount</c></param>
    /// <param name="_isGst"><c>Is GST amount</c></param>
    /// <param name="_allocItemId"><c>Item id from allocation</c></param>
    /// <returns>True if CT line is successfully created; otherwise, false.</returns>
    public boolean createChargeThroughInvoiceLine(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable,
                                                  METCBCTVendCust _metCBCTVendCust,
                                                  Amount _amount,
                                                  boolean _isGst,
                                                  ItemId _allocItemId = '')
    {
        METCBCTInvoiceLine  metCBCTInvoiceLine;
        boolean             ret = true;
        CustTable           custTable               = CustTable::find(_metCBCTInvoiceHeaderTable.CustomerAccount);
        VendTable           vendTable               = VendTable::find(_metCBCTInvoiceHeaderTable.VendorAccount);
        METVendTable        metVendTable            = METVendTable::find(vendTable.AccountNum);
        METVendParameters   metVendParameters       = MetVendParameters::find();
        VendParameters      vendParameters          = VendParameters::find();
        
        metCBCTInvoiceLine.HeaderNumber             = _metCBCTInvoiceHeaderTable.Number;
        metCBCTInvoiceLine.VendCustType             = _metCBCTVendCust;

        switch (_metCBCTInvoiceHeaderTable.InvoiceType)
        {
            case METInvoiceType::ChargeThrough:
            case METInvoiceType::ChargeThroughClaim:
                metCBCTInvoiceLine.ItemId = metVendTable.ChargeThroughServiceItemId;
                break;

            case METInvoiceType::CrossDock:
            case METInvoiceType::CrossDockClaim:
                metCBCTInvoiceLine.ItemId = metVendTable.CrossDockServiceItemId;
                break;

            case METInvoiceType::RDA:
                metCBCTInvoiceLine.ItemId = metVendTable.RDAServiceItemId;
                metCBCTInvoiceLine.LedgerDimension = vendParameters.METRDALedgerDimension;
                metCBCTInvoiceLine.Description     = _metCBCTInvoiceHeaderTable.Reference;
                break;

            case METInvoiceType::SVR:
                metCBCTInvoiceLine.ItemId = metVendTable.SVRServiceItemId;
                metCBCTInvoiceLine.LedgerDimension = vendParameters.METSVRLedgerDimension;
                metCBCTInvoiceLine.FinancialDimension = vendParameters.METSVRFinancialDimension;
                metCBCTInvoiceLine.Description     = _metCBCTInvoiceHeaderTable.Reference;
                break;

            default:
                break;
        }

        if (_allocItemId)
        {
            metCBCTInvoiceLine.ItemId               = _allocItemId;
        }
        
        metCBCTInvoiceLine.Amount                   = _amount;
                
        if (_isGst)
        {
            metCBCTInvoiceLine.TaxItemGroup             = InventTableModule::find(metCBCTInvoiceLine.ItemId, ModuleInventPurchSales::Sales).TaxItemGroupId;
        }
        
        if (!_isGst || _metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount == 0)
        {
            metCBCTInvoiceLine.TaxItemGroup             = metVendParameters.CreateLineGSTFreeGroup;
        }

        if (_metCBCTVendCust == METCBCTVendCust::Vend)
        {
            metCBCTInvoiceLine.TaxGroup                 = vendTable.TaxGroup;
        }
        else
        {
            metCBCTInvoiceLine.TaxGroup                 = custTable.TaxGroup;
        }

        // Set site and location for ChargeThrough, CrossDock, etc.
        if (_metCBCTInvoiceHeaderTable.InvoiceType !=  METInvoiceType::RDA 
            && _metCBCTInvoiceHeaderTable.InvoiceType !=  METInvoiceType::SVR)
        {
            metCBCTInvoiceLine.InventSiteId     = custTable.InventSiteId;
            metCBCTInvoiceLine.InventLocationId = custTable.InventLocation;
        }

        // Set Qty = 1 for all InvoiceTypes except SVR
        if (_metCBCTInvoiceHeaderTable.InvoiceType !=  METInvoiceType::SVR)
        {
            metCBCTInvoiceLine.Qty              = 1;
        }

        metCBCTInvoiceLine.modifiedField(fieldNum(METCBCTInvoiceLine, ItemId));
        
        if (metCBCTInvoiceLine.validateWrite())
        {
            metCBCTInvoiceLine.insert();
        }
        else
        {
            error(strFmt("@MET:CBCTInvoiceLineValidateWrite", metCBCTInvoiceLine.VendCustType, metCBCTInvoiceLine.ItemId));
            ret = false;
        }

        return ret;
    }

    /// <summary>
    /// Create invoice line
    /// </summary>
    /// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <param name="_gstPercent"><c>GSTPercent</c></param>
    /// <returns>True if CT lines are successfully created; otherwise, false.</returns>
    public boolean handleInvoiceLineCreation(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable,
                                             Percent                   _gstPercent)
    {
        boolean allocation;
        boolean ret = true;

        // CB194_ChargeThroughClaims
        // If the charge through claim invoice type matches the code specified in the parameter, then only create a ‘customer’ line on the charge through lines 
        METCustParameters METCustParameters = METCustParameters::Find();
        boolean isCrossDockClaimInvoiceType = _metCBCTInvoiceHeaderTable.InvoiceType == METCustParameters.CrossDockClaimInvoiceType ? true : false;

        //check whether the allocation exist
        if (METCBCTDeptAllocTable::existVendor(_metCBCTInvoiceHeaderTable.VendorAccount))
        {
            if(METCBCTDeptAllocTable::getTotalAllocPctperVendor(_metCBCTInvoiceHeaderTable.VendorAccount) != 100)
            {
                error("@MET:AllocationPercentageNotFullyDefinedToMatch100Pct");
                return false;
            }
            else
            {
                allocation = true;
            }
        }
        // If the GST amount is exactly 10% of the net amount, create one line for customer and one line for vendor invoice,
        // using the Item tax code of GST. If the vendor has a record in the “Vendor charge through allocation table” then split the line accordingly. 
        if (_gstPercent == 10 || _gstPercent == 0)
        {
            Amount baseAmount = _metCBCTInvoiceHeaderTable.VendInvoiceAmtInclGST - _metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount;
                    
            if (allocation && _metCBCTInvoiceHeaderTable.InvoiceType != METInvoiceType::RDA)
            {
                METCBCTDeptAllocTable metCBCTDeptAllocTable;

                while select metCBCTDeptAllocTable
                    where metCBCTDeptAllocTable.VendAccount == _metCBCTInvoiceHeaderTable.VendorAccount
                {
                    // Fixed: Replaced round(..., 2) with decRound(..., 2)
                    Amount allocatedAmount = decRound(baseAmount * (metCBCTDeptAllocTable.AllocationPct / 100.0), 2);
                    
                    ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust, allocatedAmount, NoYes::Yes, metCBCTDeptAllocTable.ServiceItemId);
                    
                    if (!ret)
                    {
                        return ret;
                    }
                    else
                    {
                        if (!isCrossDockClaimInvoiceType)
                        {
                            ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend, allocatedAmount, NoYes::Yes, metCBCTDeptAllocTable.ServiceItemId);
                            
                            if (!ret)
                            {
                                return ret;
                            }
                        }
                    }
                }
            }
            else
            {
                ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust, baseAmount, NoYes::Yes);

                if (!ret)
                {
                    return ret;
                }
                else
                {
                    if (!isCrossDockClaimInvoiceType)
                    {
                        ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend, baseAmount, NoYes::Yes);
                        
                        if (!ret)
                        {
                            return ret;
                        }
                    }
                }
            }
        }
        else if (_gstPercent < 10) //The amount is more than the GST amount
        {
            Amount baseGstAmount        = _metCBCTInvoiceHeaderTable.VendInvoiceGSTAmount * 10;
            Amount remainingBaseAmount  = this.getRemainingBaseAmount(_metCBCTInvoiceHeaderTable);

            if(allocation && _metCBCTInvoiceHeaderTable.InvoiceType != METInvoiceType::RDA)
            {
                METCBCTDeptAllocTable metCBCTDeptAllocTable;

                while select metCBCTDeptAllocTable
                    where metCBCTDeptAllocTable.VendAccount == _metCBCTInvoiceHeaderTable.VendorAccount
                {
                    // Fixed: Replaced round(..., 2) with decRound(..., 2)
                    Amount allocatedBaseAmount   = decRound(baseGstAmount * (metCBCTDeptAllocTable.AllocationPct / 100.0), 2);
                    Amount allocatedRemainAmount = decRound(remainingBaseAmount * (metCBCTDeptAllocTable.AllocationPct / 100.0), 2);

                    ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust, allocatedBaseAmount, NoYes::Yes, metCBCTDeptAllocTable.ServiceItemId);
                    
                    if (!ret)
                    {
                        return ret;
                    }
                    else
                    {
                        ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust, allocatedRemainAmount, NoYes::No, metCBCTDeptAllocTable.ServiceItemId);
                        
                        if (!ret)
                        {
                            return ret;
                        }
                        else
                        {
                            if (!isCrossDockClaimInvoiceType)
                            {
                                ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend, allocatedBaseAmount, NoYes::Yes, metCBCTDeptAllocTable.ServiceItemId);
                                
                                if (!ret)
                                {
                                    return ret;
                                }
                                else
                                {
                                    ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend, allocatedRemainAmount, NoYes::No, metCBCTDeptAllocTable.ServiceItemId);
                                
                                    if (!ret)
                                    {
                                        return ret;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            else
            {
                ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust, baseGstAmount, NoYes::Yes);
                if (!ret)
                {
                    return ret;
                }
                else
                {
                    ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust, remainingBaseAmount, NoYes::No);
                    
                    if (!ret)
                    {
                        return ret;
                    }
                    else
                    {
                        if (!isCrossDockClaimInvoiceType)
                        {
                            ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend, baseGstAmount, NoYes::Yes);
                            
                            if (!ret)
                            {
                                return ret;
                            }
                            else
                            {
                                ret = this.createChargeThroughInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend, remainingBaseAmount, NoYes::No);
                                
                                if (!ret)
                                {
                                    return ret;
                                }
                            }
                        }
                    }
                }
            }
        }

        return ret;
    }

    /// <summary>
    /// Create invoice line
    /// </summary>
    /// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <param name="_metCBCTVendCust"><c>METCBCTVendCust</c></param>
    /// <param name="_amount"><c>amount</c></param>
    /// <param name="_isWET"><c>Is WET scenario</c></param>
    /// <returns>True if CT line is successfully created; otherwise, false.</returns>
    public boolean createWEGInvoiceLine(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable,
                                        METCBCTVendCust _metCBCTVendCust,
                                        Amount _amount,
                                        boolean _isWET)
    {
        METCBCTInvoiceLine  metCBCTInvoiceLine;
        boolean             ret = true;
        CustTable           custTable               = CustTable::find(_metCBCTInvoiceHeaderTable.CustomerAccount);
        VendTable           vendTable               = VendTable::find(_metCBCTInvoiceHeaderTable.VendorAccount);
        METVendTable        metVendTable            = METVendTable::find(vendTable.AccountNum);
        VendParameters      vendParameters          = VendParameters::find();
        metCBCTInvoiceLine.HeaderNumber             = _metCBCTInvoiceHeaderTable.Number;
        metCBCTInvoiceLine.VendCustType             = _metCBCTVendCust;

        if (_metCBCTInvoiceHeaderTable.InvoiceType == METInvoiceType::ChargeThrough)
        {
            metCBCTInvoiceLine.ItemId = metVendTable.ChargeThroughServiceItemId;
        }
        else if (_metCBCTInvoiceHeaderTable.InvoiceType == METInvoiceType::CrossDock
                || _metCBCTInvoiceHeaderTable.InvoiceType == METInvoiceType::ChargeThroughClaim
                || _metCBCTInvoiceHeaderTable.InvoiceType == METInvoiceType::CrossDockClaim)
        {
            metCBCTInvoiceLine.ItemId = metVendTable.CrossDockServiceItemId;
        }
        else if (_metCBCTInvoiceHeaderTable.InvoiceType ==  METInvoiceType::RDA)
        {
            metCBCTInvoiceLine.ItemId = metVendTable.RDAServiceItemId;
            metCBCTInvoiceLine.LedgerDimension = vendParameters.METRDALedgerDimension;
            metCBCTInvoiceLine.Description     = _metCBCTInvoiceHeaderTable.Reference;
            //RDA financial dimensions are removed
           
        }
        else if (_metCBCTInvoiceHeaderTable.InvoiceType ==  METInvoiceType::SVR)
        {
            metCBCTInvoiceLine.ItemId = metVendTable.SVRServiceItemId;
            metCBCTInvoiceLine.LedgerDimension = vendParameters.METSVRLedgerDimension;
            metCBCTInvoiceLine.FinancialDimension = vendParameters.METSVRFinancialDimension;
            metCBCTInvoiceLine.Description     = _metCBCTInvoiceHeaderTable.Reference;
        }

        metCBCTInvoiceLine.Amount = _amount;
             
      
        if (_metCBCTVendCust == METCBCTVendCust::Vend)
        {
            
            metCBCTInvoiceLine.TaxGroup = vendTable.TaxGroup;

            if (_isWET)
            {
                metCBCTInvoiceLine.TaxItemGroup = InventTableModule::find(metCBCTInvoiceLine.ItemId, ModuleInventPurchSales::Sales).TaxItemGroupId;
            }
        }
        else
        {
            metCBCTInvoiceLine.TaxGroup = custTable.TaxGroup;

            if (_isWET)
            {
                metCBCTInvoiceLine.TaxItemGroup = METVendParameters::find().CreateLineWEGItemGSTGroup;
            }
        }
             
        if (!_isWET)
        {
            metCBCTInvoiceLine.TaxItemGroup = InventTableModule::find(metCBCTInvoiceLine.ItemId, ModuleInventPurchSales::Sales).TaxItemGroupId;
        }        

        // Set site and location for ChargeThrough, CrossDock, etc.
        if (_metCBCTInvoiceHeaderTable.InvoiceType !=  METInvoiceType::RDA
            && _metCBCTInvoiceHeaderTable.InvoiceType !=  METInvoiceType::SVR)
        {
            metCBCTInvoiceLine.InventSiteId     = custTable.InventSiteId;
            metCBCTInvoiceLine.InventLocationId = custTable.InventLocation;
        }

        // Set Qty = 1 for all InvoiceTypes except SVR
        if (_metCBCTInvoiceHeaderTable.InvoiceType != METInvoiceType::SVR)
        {
            metCBCTInvoiceLine.Qty = 1;
        }

        metCBCTInvoiceLine.modifiedField(fieldNum(METCBCTInvoiceLine, ItemId));
        
        if (metCBCTInvoiceLine.validateWrite())
        {
            metCBCTInvoiceLine.insert();
        }
        else
        {
            error(strFmt("@MET:CBCTInvoiceLineValidateWrite", metCBCTInvoiceLine.VendCustType, metCBCTInvoiceLine.ItemId));
            ret = false;
        }

        return ret;
    }

    /// <summary>
    /// Create invoice line
    /// </summary>
    /// <param name="_metCBCTInvoiceHeaderTable"><c>METCBCTInvoiceHeaderTable</c></param>
    /// <returns>True if CT lines are successfully created; otherwise, false.</returns>
    public boolean handleWETInvoiceLineCreation(METCBCTInvoiceHeaderTable _metCBCTInvoiceHeaderTable)
    {
        boolean ret = true;

        if (_metCBCTInvoiceHeaderTable.WETNetAmountExclWETAndGST != 0)
        {
            ret = this.createWEGInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust, 
                                            _metCBCTInvoiceHeaderTable.WETNetAmountExclWETAndGST, NoYes::Yes);

            if (!ret)
            {
                return ret;
            }
            else
            {
                ret = this.createWEGInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend,
                                                _metCBCTInvoiceHeaderTable.WETNetAmountExclWETAndGST, NoYes::Yes);

                if (!ret)
                {
                    return ret;
                }
            }
        }

        if (_metCBCTInvoiceHeaderTable.WETNETAmountExclGST != 0)
        {
            ret = this.createWEGInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Cust,
                                            _metCBCTInvoiceHeaderTable.WETNETAmountExclGST, NoYes::No);

            if (!ret)
            {
                return ret;
            }
            else
            {
                ret = this.createWEGInvoiceLine(_metCBCTInvoiceHeaderTable, METCBCTVendCust::Vend,
                                            _metCBCTInvoiceHeaderTable.WETNETAmountExclGST, NoYes::No);

                if (!ret)
                {
                    return ret;
                }
            }
        }

        return ret;
    }
